#pragma once
#include <string>
#include <fstream>
#include <stdexcept>

class INIReader;

class INIWriter {
public:
    INIWriter() = default;

    static void write(const std::string& filepath, const INIReader& reader, bool overwrite = false) noexcept(false) {
        if (!overwrite && std::ifstream(filepath)) {
            throw std::runtime_error("file already exists");
        }

        std::ofstream out(filepath);
        if (!out.is_open()) {
            throw std::runtime_error("cannot open output file");
        }

        for (const auto& section : reader.Sections()) {
            out << "[" << section << "]\n";
            for (const auto& key : reader.Keys(section)) {
                out << key << "=" << reader.Get(section, key) << "\n";
            }
        }
    }
};
